        <view class="product-provider"><view class="seller-avatar" :class="{'club-avatar':isClubProduct(selectedProduct)}" :style="{background:selectedPlayer?.color}">{{isClubProduct(selectedProduct)?'✳':selectedProduct.sellerName.slice(0,1)}}</view><view>{{isClubProduct(selectedProduct)?CLUB_NAME:selectedProduct.sellerName}}<text class="input-help">{{isClubProduct(selectedProduct)?'付款后进入公共池，由认证成员抢单':'指定成员服务 · 付款后发送邀请'}}</text></view></view>
        <view v-if="selectedPlayer" class="service-availability" :class="serviceAvailability(selectedPlayer).state"><view>{{serviceAvailability(selectedPlayer).label}}</view><text>{{serviceAvailability(selectedPlayer).hint}}</text></view>
        <view class="form-label">游戏与服务</view><view class="checkout-service"><GameIcon :game-id="selectedProduct.gameId" :size="20"/><text>{{gameName(selectedProduct.gameId)}} · {{serviceLabels[selectedProduct.serviceType]}}</text></view>
        <view class="form-label">游戏区服</view><view class="choice-row"><button v-for="r in currentGame?.regions" :key="r" :class="{selected:region===r}" @tap="region=r">{{r}}</button></view>
        <template v-if="checkoutType==='escort'"><view class="form-label">约定任务</view><view class="detail-note">{{selectedProduct.task}}</view><view class="detail-row"><text>商品价格</text><text>¥{{money(checkoutPrice)}} / 单</text></view></template>
        <view v-else class="form-inline"><view><view class="form-label">约定服务时长</view><view class="muted">¥{{compactMoney(checkoutPrice)}} / 小时</view></view><view class="quantity-control"><uni-number-box v-model="quantity" :min="1" :max="8" background="#2b2d39" color="#f5f5f5"/><text>小时</text></view></view>
        <view class="form-label">补充说明 <text>选填</text></view><textarea v-model="note" class="text-area" placeholder-class="field-placeholder" :cursor-spacing="24" :disable-default-padding="true" placeholder="希望开始的时间、游戏偏好等" :maxlength="200"/>
        <button class="agreement" @tap="agreed=!agreed"><view class="checkmark" :class="{checked:agreed}">{{agreed?'✓':''}}</view><text>{{checkoutType==='escort'?'按商品约定任务验收，服务问题可申请售后。':'按约定时长履约，服务问题可申请售后。'}}</text></button><view class="sheet-bottom"><view class="total-price"><text>合计</text>¥{{money(checkoutTotal)}}</view><button class="primary" :disabled="busy" @tap="createOrder">提交订单</button></view>
      </view>
      <view v-else-if="sheet==='pay'&&selectedOrder" class="sheet-content payment-sheet"><view class="pay-icon"><uni-icons type="weixin" :size="42" color="#72e2a0"/></view><view class="sheet-title">{{httpMode?'订单支付':acceptanceMode?'内部验收 · 模拟收银台':'微信支付 · 模拟收银台'}}</view><view class="sheet-sub">{{selectedOrder.gameName}} · {{serviceLabels[selectedOrder.serviceType]}}</view><view class="pay-amount"><text>¥</text>{{money(selectedOrder.amount)}}</view><template v-if="httpMode"><view class="simulation-note">微信与支付宝支付尚未开通，当前无法付款。订单保留 10 分钟，期间不会扣款。</view><button class="secondary full" :disabled="busy" @tap="requestPayment('wechat')">微信支付（暂未开通）</button><button class="secondary full" :disabled="busy" @tap="requestPayment('alipay')">支付宝（暂未开通）</button></template><template v-else><view class="simulation-note">这是交互演示，不会发起真实扣款。</view><button class="primary full" :disabled="busy" @tap="action('pay')">确认模拟支付</button></template><button class="text-button" @tap="sheet='order';tab='orders'">稍后支付</button></view>
      <view v-else-if="sheet==='order'&&selectedOrder" class="sheet-content"><view class="eyebrow">ORDER DETAILS</view><view class="sheet-title">{{refundFrozen(selectedOrder)?'售后处理中':statusLabels[selectedOrder.status]}}</view><view class="sheet-sub">{{selectedOrder.id}}</view><view class="detail-order-game"><view class="mini-game big" :style="{background:gameColor(selectedOrder.gameId)+'22',color:gameColor(selectedOrder.gameId)}">{{games.find(g=>g.id===selectedOrder?.gameId)?.short}}</view><view><view>{{selectedOrder.gameName}}</view><text>{{selectedOrder.region}} · {{serviceLabels[selectedOrder.serviceType]}}</text></view><view class="detail-order-price">¥{{money(selectedOrder.amount)}}</view></view><view class="detail-note">{{selectedOrder.serviceType==='escort'?'任务项：':''}}{{orderSummary(selectedOrder)}}</view><view class="detail-row"><text>下单用户</text><text>{{selectedOrder.bossName}}</text></view><view class="detail-row"><text>接单负责人</text><text>{{selectedOrder.playerName||selectedOrder.preferredPlayerName||'等待接单'}}</text></view><view v-if="selectedOrder.note" class="detail-note">{{selectedOrder.note}}</view><view v-if="selectedIncome" class="personal-income"><view class="personal-income-top"><text>{{selectedIncome.amountLabel}}</text><text class="income-state" :class="selectedIncome.status">{{selectedIncome.label}}</text></view><view class="personal-income-amount">¥{{money(selectedIncome.amount)}}</view><view class="input-help">{{selectedOrder.serviceType==='escort'?'扣除服务费后按协作人数均分，此处仅显示你的份额。':'此金额为扣除服务费后的个人净报酬。'}}</view><template v-if="selectedIncome.settlement"><view class="detail-row"><text>自动结算记录</text><text>{{selectedIncome.settlement.id}}</text></view><view class="detail-row"><text>生成时间</text><text>{{time(selectedIncome.settlement.createdAt)}}</text></view><view v-if="selectedIncome.settlement.paidAt" class="detail-row"><text>{{httpMode?'到账时间':'模拟结算时间'}}</text><text>{{time(selectedIncome.settlement.paidAt)}}</text></view></template></view><template v-if="orderMembers(selectedOrder).length"><view class="form-label">{{selectedOrder.serviceType==='escort'?'协作成员 · 净报酬均分':'服务队友'}}</view><view v-for="(member,i) in orderMembers(selectedOrder)" :key="member.playerId" class="team-member"><view><view>{{member.name}} <text class="muted">{{i===0?'负责人':'副手'}}</text></view><text class="muted">{{member.playerId===me?.id?selectedIncome?.label:refundFrozen(selectedOrder)?'售后暂停结算':selectedOrder.status==='completed'?(selectedOrder.settlementStatus==='credited'?'已记账 · 待渠道转账':selectedOrder.settlementStatus==='paid'||selectedOrder.timeline.some(e=>e.label==='系统自动结算完成（模拟）')?'已自动结算':'自动结算处理中'):'确认完成后自动结算'}}</text></view><text class="lime">¥{{money(participantEarnings(selectedOrder,member.playerId))}}</text><button v-if="i>0&&isLead(selectedOrder)&&selectedOrder.status==='accepted'&&!refundFrozen(selectedOrder)" class="text-button" :disabled="busy" @tap="action('remove-assistant',selectedOrder,{playerId:member.playerId})">移除</button></view><button v-if="isLead(selectedOrder)&&selectedOrder.serviceType==='escort'&&selectedOrder.status==='accepted'&&!refundFrozen(selectedOrder)" class="secondary full" @tap="sheet='assistants'">＋ 添加副手</button><view v-if="selectedOrder.serviceType==='escort'" class="input-help">净报酬 ¥{{money(selectedOrder.earnings)}}，按 {{orderMembers(selectedOrder).length}} 人均分。开始服务后名单锁定，成员均可查看订单及本人报酬。</view></template>
        <view v-if="selectedOrder.serviceType==='hourly'&&selectedOrder.status==='serving'" class="notice"><text>{{countdown(selectedOrder)}}</text><button v-if="!httpMode&&isLead(selectedOrder)&&remaining(selectedOrder)>0" class="text-button" :disabled="busy||refundFrozen(selectedOrder)" @tap="action('demo-elapse')">模拟走满时长</button></view><view v-if="selectedOrder.refundStatus!=='none'" class="refund-info"><view>售后：{{refundFrozen(selectedOrder)?'待审核':selectedOrder.refundStatus==='refunded'?(httpMode?'已原路退款':'已模拟退款'):'未通过'}}</view><text>申请 ¥{{money(selectedOrder.refundAmount||0)}} · {{selectedOrder.refundReason}}</text><text v-if="selectedOrder.refundReviewNote">{{selectedOrder.refundReviewNote}}</text></view><view class="form-label">订单动态</view><view class="timeline"><view v-for="(e,i) in selectedOrder.timeline" :key="i" class="timeline-item"><view class="timeline-dot"/><view><view>{{e.label}}</view><text>{{time(e.at)}} · {{e.actor}}</text><view v-if="e.note" class="timeline-note">{{e.note}}</view></view></view></view><view class="detail-actions"><button v-if="isInvited(selectedOrder)" class="primary" :disabled="busy" @tap="action('accept')">接受邀请</button><button class="secondary" @tap="sheet='help'">联系客服</button><template v-if="isMine(selectedOrder)"><button v-if="selectedOrder.status==='unpaid'" class="secondary" :disabled="busy" @tap="action('cancel')">取消订单</button><button v-if="selectedOrder.status==='unpaid'" class="primary" @tap="payOrder(selectedOrder)">去付款</button><button v-if="selectedOrder.status==='confirming'&&!refundFrozen(selectedOrder)" class="primary" :disabled="busy" @tap="action('confirm')">确认完成</button><button v-if="selectedOrder.paidAt&&selectedOrder.status!=='cancelled'&&['none','rejected'].includes(selectedOrder.refundStatus)&&!selectedOrder.settlementId" class="secondary" @tap="refund(selectedOrder)">申请退款</button></template><template v-if="isLead(selectedOrder)&&!refundFrozen(selectedOrder)"><button v-if="selectedOrder.status==='accepted'" class="primary" :disabled="busy" @tap="action('start')">开始服务</button><button v-if="selectedOrder.status==='serving'" class="primary" :disabled="busy||(selectedOrder.serviceType==='hourly'&&remaining(selectedOrder)>0)" @tap="finish(selectedOrder)">{{selectedOrder.serviceType==='escort'?'提交任务验收':'提交完成'}}</button></template></view></view>
      <view v-else-if="sheet==='assistants'&&selectedOrder" class="sheet-content"><view class="eyebrow">BETTER AS A TEAM</view><view class="sheet-title">添加副手</view><view class="sheet-sub">护航考核通过且支持该游戏的在线成员。加入后均分净报酬，开始服务后锁定名单。</view><button v-for="p in assistantCandidates" :key="p.id" class="role-card" :disabled="busy" @tap="action('add-assistant',selectedOrder,{playerId:p.id})"><view class="role-icon">{{p.name.slice(0,1)}}</view><view><view>{{p.name}}</view><text>{{p.subtitle}}</text></view><text>＋</text></button><view v-if="!assistantCandidates.length" class="empty">暂无可添加成员</view></view>
      <view v-else-if="sheet==='apply'" class="sheet-content"><view class="eyebrow">LET YOUR SKILLS SHINE</view><view class="sheet-title">申请入驻 · {{gameName(applyGame)}}{{applyType==='escort'?'护航':'组队'}}</view><view class="sheet-sub">提交申请 → 资料审核 → 专项考核 → 开通商品发布与接单</view><view class="apply-scope"><GameIcon :game-id="applyGame" :size="24"/><view>{{gameName(applyGame)}}<text>{{applyType==='escort'?'护航 · 按任务验收':'组队 · 按时长履约'}}</text></view></view><view class="form-label">游戏经验与服务说明</view><textarea v-model="introduction" class="text-area" placeholder-class="field-placeholder" :cursor-spacing="24" :disable-default-padding="true" placeholder="介绍你的游戏经验、擅长内容及可参加考核的时间，至少 10 字。" :maxlength="500"/><view class="simulation-note">本次仅申请入驻{{gameName(applyGame)}}的{{applyType==='escort'?'护航':'组队'}}服务。通过后仅可发布、接取该游戏该类型的商品与订单，其他游戏或服务类型需要另行考核。</view><button class="primary full" :disabled="busy" @tap="submitApplication">提交申请</button></view>
      <view v-else-if="sheet==='refund'&&selectedOrder" class="sheet-content"><view class="sheet-title">申请售后退款</view><view class="sheet-sub">俱乐部会核实服务记录并处理你的申请。</view><view class="form-label">退款金额（元）</view><input v-model="refundAmount" class="form-input" placeholder-class="field-placeholder" :cursor-spacing="24" type="digit"/><view class="input-help">最高 ¥{{money(selectedOrder.amount)}}，支持部分退款。</view><view class="form-label">退款原因 <text>选填</text></view><textarea v-model="refundReason" class="text-area" placeholder-class="field-placeholder" :cursor-spacing="24" :disable-default-padding="true" placeholder="可补充遇到的问题，也可以直接提交售后" :maxlength="200"/><button class="primary full" :disabled="busy" @tap="action('refund',selectedOrder,{amount:Math.round(Number(refundAmount)*100),reason:refundReason})">提交退款申请</button></view>
      <view v-else-if="sheet==='finish'&&selectedOrder" class="sheet-content"><view class="eyebrow">GG, WELL PLAYED</view><view class="sheet-title">{{selectedOrder.serviceType==='escort'?'提交任务验收':'提交服务记录'}}</view><view class="sheet-sub">提交后由下单用户确认，随后系统自动结算净报酬。</view><view v-if="selectedOrder.serviceType==='escort'" class="detail-note">任务项：{{selectedOrder.task}}</view><view class="form-label">完成记录</view><textarea v-model="finishNote" class="text-area" placeholder-class="field-placeholder" :cursor-spacing="24" :disable-default-padding="true" :placeholder="selectedOrder.serviceType==='escort'?'说明任务达成情况及验收依据':'说明已完成的服务时长与情况'" :maxlength="200"/><button v-if="selectedOrder.serviceType==='escort'" class="agreement" @tap="taskConfirmed=!taskConfirmed"><view class="checkmark" :class="{checked:taskConfirmed}">{{taskConfirmed?'✓':''}}</view><text>确认已完成订单约定的指定任务</text></button><button class="primary full" :disabled="busy" @tap="action('finish',selectedOrder,{note:finishNote,taskCompleted:taskConfirmed})">提交完成</button></view>
      <view v-else-if="sheet==='help'" class="sheet-content"><view class="eyebrow">ALWAYS ON YOUR SIDE</view><view class="sheet-title">帮助与客服</view><view class="sheet-sub">服务遇到问题，可在订单详情申请售后。</view><view class="help-card"><uni-icons type="headphones" :size="35" color="#d9fd88"/><view><view>俱乐部服务支持</view><text>{{httpMode?'可通过俱乐部现有客服渠道联系工作人员。':'当前为交互演示，真实客服尚未接入。'}}</text></view></view><view class="detail-bio">组队订单按约定时长完成；护航订单按指定任务验收。新用户默认尚未入驻。每个游戏的组队与护航分别申请入驻，通过对应考核后，才可发布对应商品或接取对应订单。</view><view class="sheet-footnote">{{acceptanceMode?'验收数据保存在服务器独立测试库，两端共享；收付款均为模拟。':httpMode?'订单有争议时请先提交售后，相关处理进展可在订单中查看。':'模拟数据保存在'+deviceDataLabel+'，不同设备之间独立。'}}</view></view>
    </scroll-view></view></view><view v-if="toast" class="toast"><uni-icons type="info" color="#d9fd88" :size="18"/>{{toast}}</view>
    </template>
  </view>
</template>

